  $q$TRUNCATE twin.audit_events$q$,
  $q$CREATE TABLE twin.provisioner_probe(x int)$q$,
  $q$ALTER TABLE twin.memberships DISABLE ROW LEVEL SECURITY$q$,
  $q$DROP POLICY tenant_isolation ON twin.memberships$q$
]) AS s;
SET LOCAL ROLE twin_owner;
SELECT set_config('app.oidc_issuer','https://test.invalid',true), set_config('app.oidc_subject','subject_a',true),
       set_config('app.organization_id','org_01M4YDQK00TA00000000000000',true), set_config('app.user_id','usr_01M4YDQK00TA00000000000001',true);

-- Defence in depth: the guards hold even with a broader worker grant (e.g.
-- pg_write_all_data) and a shadowing function earlier on the search_path
-- (clusters upgraded from PG14 still let PUBLIC create in schema public).
RESET ROLE;
GRANT UPDATE ON twin.imports TO twin_worker;
GRANT CREATE ON SCHEMA public TO twin_worker;
SET LOCAL ROLE twin_worker;
CREATE FUNCTION public.pg_has_role(name, text, text) RETURNS boolean LANGUAGE sql AS 'SELECT false';
SET LOCAL search_path = public, pg_catalog;
SELECT pg_temp.must_fail(s, '42501') FROM unnest(ARRAY[
  $q$UPDATE twin.imports SET status='FAILED' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET mapping='{"a":1}' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000002'$q$,
  $q$UPDATE twin.imports SET mapping_revision=7 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000002'$q$,
  $q$UPDATE twin.imports SET proposal_id='aip_01M4YDQK00TA00000000000001' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000002'$q$
]) AS s;
SET LOCAL search_path TO DEFAULT;
RESET ROLE;
REVOKE UPDATE ON twin.imports FROM twin_worker;
GRANT UPDATE (status,total_rows,invalid_rows,preview,validation,mapping_suggestion_status,
  mapping_suggestion,error,error_report_object_key) ON twin.imports TO twin_worker;
REVOKE CREATE ON SCHEMA public FROM twin_worker;
DROP FUNCTION public.pg_has_role(name, text, text);

-- TEST-011 (structural): FORCE RLS everywhere, runtime and provisioning roles
-- separate and owning nothing, worker without identity, membership or
-- idempotency access, provisioning with only its five grants (D-042).
SET LOCAL ROLE twin_owner;
SELECT pg_temp.check(count(*)=0, 'tables without FORCE RLS or a policy: ' || coalesce(string_agg(c.relname, ', '), ''))
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='twin' AND c.relkind='r'
    AND (NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid));
SELECT pg_temp.check(count(*)=0, 'objects owned by a runtime role: ' || coalesce(string_agg(d.classid::regclass || ' ' || d.objid, ', '), ''))
  FROM pg_shdepend d
  WHERE d.deptype='o' AND d.refclassid='pg_authid'::regclass AND pg_get_userbyid(d.refobjid) IN ('twin_api','twin_worker','twin_provisioner')
    AND d.dbid IN (0, (SELECT oid FROM pg_database WHERE datname=current_database()));
SELECT pg_temp.check(count(*)=0, 'twin functions without a fixed search_path: ' || coalesce(string_agg(p.proname, ', '), ''))
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='twin' AND NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%');
SELECT pg_temp.check(NOT pg_has_role(a, b, 'MEMBER'), format('%s must not be a member of %s', a, b))
  FROM (VALUES ('twin_api','twin_owner'),('twin_worker','twin_owner'),('twin_api','twin_worker'),('twin_worker','twin_api'),
               ('twin_provisioner','twin_owner'),('twin_provisioner','twin_api'),('twin_provisioner','twin_worker'),
               ('twin_api','twin_provisioner'),('twin_worker','twin_provisioner')) AS t(a, b);
-- D-042: twin_provisioner's table privileges are exactly these.
SELECT pg_temp.check(has_table_privilege('twin_provisioner', 'twin.' || c.relname, p) =
    ((c.relname, p) IN (('users','SELECT'),('users','INSERT'),('organizations','INSERT'),('memberships','INSERT'),('audit_events','INSERT'))),
    format('twin_provisioner %s on %s', p, c.relname))
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace,
       unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) AS p
  WHERE n.nspname='twin' AND c.relkind='r';
SELECT pg_temp.check(NOT has_schema_privilege('twin_provisioner', 'twin', 'CREATE'), 'twin_provisioner cannot create in twin');
-- T-010 review 2 (L1): provisioning adds members and audit events only to
-- an organization its own transaction created. The behaviour needs a second
-- transaction (internal/storage/provisioning); here, that the guard is in
-- place: a trigger on both tables, a definer function with a fixed
-- search_path that only provisioning may call.
SELECT pg_temp.check(count(*)=2, 'guard_provisioner_target is a BEFORE INSERT row trigger on memberships and audit_events')
  FROM pg_trigger g
  WHERE g.tgname='guard_provisioner_target' AND g.tgenabled='O' AND g.tgtype & 7 = 7 AND g.tgtype & 24 = 0
    AND g.tgrelid IN ('twin.memberships'::regclass, 'twin.audit_events'::regclass);
SELECT pg_temp.check(p.prosecdef AND p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp'],
    'created_in_this_transaction is SECURITY DEFINER with a fixed search_path')
  FROM pg_proc p WHERE p.oid='twin.created_in_this_transaction(text)'::regprocedure;
SELECT pg_temp.check(has_function_privilege(r, 'twin.created_in_this_transaction(text)', 'EXECUTE') = (r='twin_provisioner'),
    format('%s EXECUTE on created_in_this_transaction', r))
  FROM unnest(ARRAY['twin_provisioner','twin_api','twin_worker']) AS r;
-- ADR-023: membership changes cannot deadlock because membership rows are
-- locked only by tenant.RunOwners and by tenant.Run's first FOR SHARE. A
-- foreign key to memberships would add row locks from other tables' writes.
SELECT pg_temp.check(count(*)=0, 'foreign keys referencing twin.memberships: ' || coalesce(string_agg(conname, ', '), ''))
  FROM pg_constraint WHERE contype='f' AND confrelid='twin.memberships'::regclass;
SELECT pg_temp.check(NOT has_table_privilege('twin_worker', 'twin.' || t, p), format('worker has no %s on %s', p, t))
  FROM unnest(ARRAY['users','memberships','idempotency_keys','model_drafts']) AS t,
       unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) AS p;
SELECT pg_temp.check(count(*)=0, 'twin functions executable by PUBLIC: ' || coalesce(string_agg(p.proname, ', '), ''))
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='twin' AND has_function_privilege('public', p.oid, 'EXECUTE');
SELECT pg_temp.check(NOT has_table_privilege('twin_worker', 'twin.' || t, 'INSERT'), format('worker cannot INSERT into %s', t))
  FROM unnest(ARRAY['model_versions','scenarios','model_version_datasets','imports','ai_proposals','simulation_runs']) AS t;

ROLLBACK;
